'use strict';
function main(){
var m=76.2,A=0.9,rho=1.225,g=9.81;
var T=m*g,P=Math.pow(T,1.5)/Math.sqrt(2*rho*A)/1000;
return {mass_kg:m, rotor_disk_m2:A, hover_power_kw:Math.round(P*10)/10};
}
try{var out=main();console.log(JSON.stringify(out));}catch(e){console.log(JSON.stringify({error:String(e&&e.message||e)}));process.exitCode=1;}

